SINA_SMART["biochem1-carb-metabolism"] = {"lecture":"biochem1-carb-metabolism","title":"Carbohydrate metabolism","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biochem1-carb-metabolism:e0","text":"Metabolism = anabolism + catabolism.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e1","text":"Glycaemia 3.9-5.6 mmol/L (0.7-1.1 g/L).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e2","text":"Glycolysis (cytosol): glucose → 2 pyruvate; net 2 ATP + 2 NADH.","topic":"Glycolysis and pyruvate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e3","text":"Regulated steps: hexokinase/glucokinase, PFK-1, pyruvate kinase.","topic":"Glycolysis and pyruvate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e4","text":"Pyruvate fates: lactate (Cori cycle), ethanol (yeast), acetyl-CoA (PDH).","topic":"Glycolysis and pyruvate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e5","text":"NADH = 2.5 ATP, FADH₂ = 1.5 ATP; glucose → 30-32 ATP.","topic":"Glycolysis and pyruvate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e6","text":"Shuttles: malate-aspartate (2.5) and glycerol-3-P (1.5).","topic":"Glycolysis and pyruvate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e7","text":"Glycogenesis: UDP-glucose, glycogenin, glycogen synthase; insulin.","topic":"Glycogen","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e8","text":"Glycogenolysis: phosphorylase; glucagon, adrenaline; G6Pase in liver only.","topic":"Glycogen","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e10","text":"Pentose phosphate: NADPH + ribose-5-P; G6PD.","topic":"Gluconeogenesis and pentose phosphate pathway","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carb-metabolism:e9","text":"Gluconeogenesis: liver and kidney; lactate, glycerol, amino acids (not Leu, Lys).","topic":"Gluconeogenesis and pentose phosphate pathway","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1wqt27c":"a","13ajcmb":"a","5ardey":"a","1jgbwbp":"a","1k43feg":"a","s0ialq":"a","ukwqrn":"a","55l66l":"a","oncbij":"a","1tir2eu":"a","1tbd2bw":"a","1wd05fg":"a","1fudea8":"a","xm51ip":"a","1wirfai":"a","1l342pi":"a"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biochem1-carb-metabolism:e0":{"s":0,"u":["Metabolism = anabolism + catabolism.","Metabolism = anabolism + catabolism ."],"dp":[]},"biochem1-carb-metabolism:e1":{"s":0,"u":["Glycaemia 3.9-5.6 mmol/L (0.7-1.1 g/L).","Glycaemia (blood glucose) is normally 3.9-5.6 mmol/L (0.7-1.1 g/L) : below 0.7 g/L hypoglycaemia, above 1.1 g/L hyperglycaemia (diabetes)."],"dp":[]},"biochem1-carb-metabolism:e2":{"s":1,"u":["Glycolysis (cytosol): glucose → 2 pyruvate; net 2 ATP + 2 NADH.","Net: 2 ATP + 2 NADH per glucose.","Glycolysis converts glucose into 2 pyruvate in the cytoplasm ."],"dp":[]},"biochem1-carb-metabolism:e3":{"s":1,"u":["Regulated steps: hexokinase/glucokinase, PFK-1, pyruvate kinase.","Irreversible regulated steps: reaction 1 (hexokinase/glucokinase : glucose → glucose-6-P), reaction 3 (phosphofructokinase-1) and reaction 10 (pyruvate kinase)."],"dp":[]},"biochem1-carb-metabolism:e4":{"s":1,"u":["Pyruvate fates: lactate (Cori cycle), ethanol (yeast), acetyl-CoA (PDH).","Fates of pyruvate: lactic fermentation (hypoxia, anaerobic muscle; lactate returns to the liver: Cori cycle ), alcoholic fermentation (yeast), or aerobic oxidation : pyruvate dehydrogenase → acetyl-CoA → Krebs cycle → respiratory chain (mobile carriers ubiquinone Q and cytochrome c; oxidative phosphorylation)."],"dp":[]},"biochem1-carb-metabolism:e5":{"s":1,"u":["NADH = 2.5 ATP, FADH₂ = 1.5 ATP; glucose → 30-32 ATP.","Yield: NADH = 2.5 ATP, FADH₂ = 1.5 ATP; total 30-32 ATP per glucose .","Net: 2 ATP + 2 NADH per glucose."],"dp":[]},"biochem1-carb-metabolism:e6":{"s":1,"u":["Shuttles: malate-aspartate (2.5) and glycerol-3-P (1.5).","Shuttles bring cytosolic NADH into mitochondria: malate-aspartate (liver, heart, kidney: 2.5 ATP) and glycerol-3-phosphate (muscle, brain: 1.5 ATP)."],"dp":[]},"biochem1-carb-metabolism:e7":{"s":2,"u":["Glycogenesis: UDP-glucose, glycogenin, glycogen synthase; insulin.","Glycogenesis (cytosol): glucose activated as UDP-glucose (uses ATP and UTP), primed by glycogenin , extended by glycogen synthase and branched by the branching enzyme; occurs when glucose is high; activated by insulin in liver, inhibited by glucagon (liver) and adrenaline (muscle)."],"dp":[]},"biochem1-carb-metabolism:e8":{"s":2,"u":["Glycogenolysis: phosphorylase; glucagon, adrenaline; G6Pase in liver only.","Glycogenolysis : glycogen phosphorylase , phosphoglucomutase, debranching enzyme and (liver only) glucose-6-phosphatase ; in liver it maintains blood glucose, in muscle it fuels contraction; triggered by fasting and intense effort, activated by glucagon and adrenaline .","Glycogenesis (cytosol): glucose activated as UDP-glucose (uses ATP and UTP), primed by glycogenin , extended by glycogen synthase and branched by the branching enzyme; occurs when glucose is high; activated by insulin in liver, inhibited by glucagon (liver) and adrenaline (muscle)."],"dp":[{"h":"Why muscle glycogen cannot raise blood sugar","t":"Muscle lacks glucose-6-phosphatase, so the glucose-6-phosphate released from its glycogen stays trapped in the cell and is burned for contraction. Only the liver (and kidney) can remove the phosphate and export free glucose, which is why the liver's much smaller store, not muscle's larger one, maintains blood glucose between meals. Source: the lecture's glycogenolysis slides."}]},"biochem1-carb-metabolism:e10":{"s":3,"u":["Pentose phosphate: NADPH + ribose-5-P; G6PD.","Pentose phosphate pathway (hexose monophosphate shunt, cytosol): produces NADPH and ribose-5-phosphate ; key enzyme glucose-6-phosphate dehydrogenase (G6PD) ; its deficiency makes red cells vulnerable to oxidative haemolysis."],"dp":[]},"biochem1-carb-metabolism:e9":{"s":3,"u":["Gluconeogenesis: liver and kidney; lactate, glycerol, amino acids (not Leu, Lys).","Gluconeogenesis : synthesis of glucose from non-carbohydrate substrates ( lactate, pyruvate, glycerol, glucogenic amino acids : all except leucine and lysine ) in the liver and kidney , to supply the brain (120-160 g/day) and red cells."],"dp":[]}},"meta":{"1wqt27c":{"a":"recall","vg":"biochem1-carb-metabolism:e1/recall/1"},"13ajcmb":{"a":"recall","vg":"biochem1-carb-metabolism:e2/recall/1"},"5ardey":{"a":"recall","vg":"biochem1-carb-metabolism:e2/recall/2"},"1jgbwbp":{"a":"recall","vg":"biochem1-carb-metabolism:e3/recall/1"},"1k43feg":{"a":"recall","vg":"biochem1-carb-metabolism:e4/recall/1"},"s0ialq":{"a":"recall","vg":"biochem1-carb-metabolism:e4/recall/2"},"ukwqrn":{"a":"recall","vg":"biochem1-carb-metabolism:e4/recall/3"},"55l66l":{"a":"recall","vg":"biochem1-carb-metabolism:e5/recall/1"},"oncbij":{"a":"recall","vg":"biochem1-carb-metabolism:e5/recall/1"},"1tir2eu":{"a":"recall","vg":"biochem1-carb-metabolism:e6/recall/1"},"1tbd2bw":{"a":"recall","vg":"biochem1-carb-metabolism:e7/recall/1"},"1wd05fg":{"a":"recall","vg":"biochem1-carb-metabolism:e8/recall/1"},"1fudea8":{"a":"recall","vg":"biochem1-carb-metabolism:e8/recall/2"},"xm51ip":{"a":"recall","vg":"biochem1-carb-metabolism:e9/recall/1"},"1wirfai":{"a":"recall","vg":"biochem1-carb-metabolism:e9/recall/2"},"1l342pi":{"a":"recall","vg":"biochem1-carb-metabolism:e10/recall/1"}},"explRev":"ba7a6e01ac6e"};
